func temporalType(value string) string {
	for _, candidate := range []struct {
		layout string
		typ    string
	}{
		{"2006-01-02T15:04:05.999999999Z07:00", "datetime"},
		{"2006-01-02 15:04:05.999999999Z07:00", "datetime"},
		{"2006-01-02T15:04:05.999999999", "datetime-local"},
		{"2006-01-02 15:04:05.999999999", "datetime-local"},
		{"2006-01-02", "date-local"},
		{"15:04:05.999999999", "time-local"},
	} {
		if _, err := time.Parse(candidate.layout, value); err == nil {
			return candidate.typ
		}
	}
	return ""
}

func matchingDelimiter(text string, open, close byte) (int, error) {
	depth := 0
	quote := byte(0)
	for i := 0; i < len(text); i++ {
		if quote != 0 {
			if quote == '"' && text[i] == '\\' {
				i++
				continue
			}
			if text[i] == quote {
				quote = 0
			}
			continue
		}
		if text[i] == '\'' || text[i] == '"' {
			quote = text[i]
			continue
		}
		switch text[i] {
		case open:
			depth++
		case close:
			depth--
			if depth == 0 {
				return i, nil
			}
		}
	}
	return 0, fmt.Errorf("unterminated array")
