		switch text[1] {
		case 'x':
			base, text = 16, text[2:]
		case 'o':
			base, text = 8, text[2:]
		case 'b':
			base, text = 2, text[2:]
		}
	}
	if signed && base != 10 {
		return false
	}
	if text == "" || !validDigits(text, base) {
