		case r >= '0' && r <= '9':
			value = int(r - '0')
		case r >= 'a' && r <= 'f':
			value = int(r-'a') + 10
		case r >= 'A' && r <= 'F':
			value = int(r-'A') + 10
		}
		if value < 0 || value >= base {
			return false
		}
		previousUnderscore = false
	}
	return true
